links = {'c1': ['s1', 'c0'], 'c0': ['s0']}
def backtrace(cid, depth=0):
    if depth > 5: return ['...cycle cap']
    out = []
    for s in links.get(cid, []):
        out.append(s)
        out += backtrace(s, depth + 1)
    return out
print('ancestry of c1:', backtrace('c1'))

