import hashlib
src = {'s1': 'inverted index data'}
link = {'sid': 's1', 'hash': hashlib.sha256(src['s1'].encode()).hexdigest()}
ok = link['sid'] in src and hashlib.sha256(src[link['sid']].encode()).hexdigest() == link['hash']
print('link integrity:', 'OK' if ok else 'BROKEN -> invalidate')

